import{_ as t}from"./chunks/folders.9ioZn9MV.js";import{_ as e,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"比较文件夹","description":"一次看全新增、修改与缺失的文件，按状态筛选，并让两边恢复一致。","frontmatter":{"title":"比较文件夹","description":"一次看全新增、修改与缺失的文件，按状态筛选，并让两边恢复一致。"},"headers":[],"relativePath":"zh-CN/guide/folders.md","filePath":"zh-CN/guide/folders.md","lastUpdated":1793948370000}'),s={name:"zh-CN/guide/folders.md"};function l(n,a,d,c,h,p){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="比较文件夹" tabindex="-1">比较文件夹 <a class="header-anchor" href="#比较文件夹" aria-label="Permalink to &quot;比较文件夹&quot;">​</a></h1><p>两个本该一致的文件夹 —— 工作副本和备份、旧导出和新导出 —— 逐个文件去对， 实在太累。qDiff 把整棵树一次摆出来。</p><img src="'+t+'" alt="两列文件夹树，文件状态用颜色区分" class="guide-shot"><h2 id="打开两个文件夹" tabindex="-1">打开两个文件夹 <a class="header-anchor" href="#打开两个文件夹" aria-label="Permalink to &quot;打开两个文件夹&quot;">​</a></h2><p>把两个文件夹拖进窗口，或者从「文件 → 打开」里选。里面的子文件夹也会一起比， 看到的是完整全貌。</p><h2 id="一眼读懂这棵树" tabindex="-1">一眼读懂这棵树 <a class="header-anchor" href="#一眼读懂这棵树" aria-label="Permalink to &quot;一眼读懂这棵树&quot;">​</a></h2><ul><li><strong>绿色</strong> —— 只有一边有这个文件。</li><li><strong>橙色</strong> —— 名字一样，内容不一样。</li><li><strong>红色</strong> —— 另一边少了这个文件。</li><li><strong>灰色</strong> —— 两边一致。</li></ul><h2 id="只看想看的" tabindex="-1">只看想看的 <a class="header-anchor" href="#只看想看的" aria-label="Permalink to &quot;只看想看的&quot;">​</a></h2><p>用状态筛选把已经一致的文件藏起来，也可以输入名称的一部分来缩小范围。 可以只核对文件名，也可以连内容一起核对 —— 备份看起来齐全、里面却是旧内容时， 特别有用。</p><p>文件夹再大也能很快出结果，不用盯着进度条等。</p><h2 id="在列表里顺手整理" tabindex="-1">在列表里顺手整理 <a class="header-anchor" href="#在列表里顺手整理" aria-label="Permalink to &quot;在列表里顺手整理&quot;">​</a></h2><p>把文件复制到另一边、删掉多余的、或让一组文件同步一致，都在这棵树里完成， 不用切回访达。</p><div class="tip custom-block"><p class="custom-block-title">放心先看看</p><p>在你主动选择某个操作之前，磁盘上的内容不会有任何改动。单纯浏览、筛选比较 是完全安全的。</p></div><p>接下来：<a href="./projects.html">提交前把项目看一遍</a>。</p>',14)])])}const m=e(s,[["render",l]]);export{f as __pageData,m as default};
